#!/usr/bin/env bash
# Tests for the build-input logic of onnxruntime-split/PKGBUILD: how
# prepare() resolves and checks ORTF_EPS, ORTF_CUDA_ARCHS, its presets,
# ORTF_NVCC_THREADS, ORTF_TENSORRT_HOME (and the TensorRT version its
# headers give), ORTF_PYTHON, ORTF_CCACHE, MAKEFLAGS, NVCC_CCBIN, the
# CUDA major (cuda.h against nvcc) and CFLAGS/CXXFLAGS (_ortf_resolve),
# how it lays out the dependency mirror (_ortf_mirror), which
# site-packages the Python package goes to under /usr/bin/python and a
# venv (_ortf_py_site), the package names the inputs give
# (_ortf_cuda_header_major, _ortf_cuda_suffix, _ortf_pkgnames,
# _ortf_check_names), the TensorRT header version, the installed
# openvino, python, migraphx and hip-runtime-amd versions and the ROCm
# sonames prepare() records and the bounds they give
# (_ortf_installed_version, _ortf_minor_bounds, _ortf_major_bounds,
# _ortf_rocm_soname_major), the depends a library's DT_NEEDED entries
# give (_ortf_lib_depends, on the real lists of a 1.29.0 build; the
# MIGraphX provider's is a stand-in), the package functions of every
# package run as makepkg runs them (set -eE) on a stub install (each
# with cpuinfo's and protobuf's licences, the CUDA one also with
# cudnn-frontend's; bare names of bounded dependencies dropped), that of
# `makepkg --printsrcinfo` only the package names (and, with tensorrt or
# migraphx, makedepends; with dnnl, its optdepends; the MIGraphX
# optdepend, naming onnxruntime-split-migraphx, is in every build)
# depend on the inputs, from the environment or from the PKGBUILD's
# _ortf_default_* lines (a copy with another line), and that every
# dependency between the packages is met by the packages' names and
# provides, and by those of their -bin counterparts (the convention at
# the top of the PKGBUILD). The same for the cuda12 line's recipe,
# onnxruntime-split-cuda12/PKGBUILD (generated by
# scripts/gen-cuda12.sh): the legacy preset and the CUDA major each
# preset needs, its one package and its onnxruntime-core=<pkgver> pin
# (met by the main line's packages and their -bin counterparts), its
# cuDNN major.minor bound, its refusal of CUDA 13 libraries in the
# NEEDED entries, the stage its CUDA package installs itself (no
# onnxruntime-core runs before it), its .SRCINFO, and build()'s
# -Wno-deprecated-gpu-targets for CUDA 12 only. Its pin is now the pair
# onnxruntime-core>=1.29.0-7 and <1.29.1 (the main line's cores built
# with the training ops, which build() turns on in every line), met by
# the main line's 1.29.0-7 and later pkgrels, not by 1.29.0-6;
# onnxruntime-core conflicts with the line's earlier packages. The
# oneDNN provider (dnnl, in the default inputs): its package with no
# onednn and with libgomp, oneDNN's licence and notices, a libdnnl
# NEEDED refused, the cmake/external/dnnl.cmake patch (_ortf_patch_dnnl)
# on the upstream text and its loud failure when that text changed. The
# WebGPU provider (webgpu, in the default inputs): prepare()'s check of
# Arch's CMake packages Dawn builds against, of jinja2 and markupsafe
# for the system python and of the installed spirv-headers and
# vulkan-headers, whose versions it records; its package with
# vulkan-icd-loader and the licences of Dawn, SPIRV-Headers and
# Vulkan-Headers, a shared Dawn or a SPIRV-Tools NEEDED refused,
# build()'s plugin, Python3, the CMake packages' directories and
# GIT_CEILING_DIRECTORIES, and the Dawn, install and Python module
# patches (_ortf_patch_dawn, _ortf_patch_webgpu_install,
# _ortf_patch_pybind_webgpu) and the Conv patch
# (_ortf_patch_webgpu_conv) on the upstream texts, each failing loudly
# on a patched file; Dawn's archive in the main line's sources only. The
# migraphx line's recipe, onnxruntime-split-migraphx/PKGBUILD
# (scripts/gen-migraphx.sh): migraphx alone and no Python, its one
# package with the same pin pair, its .SRCINFO with no CUDA. The
# training Python package: build() builds the wheel with setup.py's
# --enable_training, LazyTensor off and RTTI on
# (onnxruntime_DISABLE_RTTI=OFF) in every line, the setup.py patch
# keeping the distribution name onnxruntime (_ortf_patch_setup) on the
# upstream text and its loud failure, and python-onnxruntime-core's
# training depends, its python-pytorch optdepend and its refusal of a
# wheel without onnxruntime.training.ortmodule or under another
# distribution name. The TensorBoard protos' patch
# (_ortf_patch_tensorboard): protoc names each proto as the others
# import it and writes it where upstream does, on the upstream text, and
# its loud failure on a patched file. The Python module's provider list
# (_ortf_patch_pybind_providers): the _pybind_state.py.in patch on the
# upstream text, and its loud failure on a patched or changed file. The
# CUDA provider's cuDNN link (_ortf_patch_cudnn_link, with the
# ShardedMoE drop on the same file) and the oneDNN factory's copy of its
# thread count (_ortf_patch_dnnl_threadpool_args), on the upstream
# texts, each failing loudly on a patched file. The package-time symbol
# guard (_ortf_check_symbols, on a stub ldd): an undefined symbol, a
# NEEDED library not found or a missing symbol version fails the
# package, the provider bridge's Provider_GetHost and Provider_SetHost
# pass; a libcudnn NEEDED gives the recorded cuDNN bounds alone
# (major.minor in the cuda12 line). The MIGraphX package's link into the
# Python module: in the migraphx line too (no Python package in its
# build), with python bounded to its site-packages' minor and a
# python-onnxruntime-core optdepend, and prepare()'s early check of the
# system python there. The source (ORTF_SOURCE): the mirror's archive by
# default, with its b2sum and in noextract, the git tag with upstream,
# an invalid value still sourced (the mirror's) and refused by
# prepare(); the tree of the recorded layout (_ortf_srcroot) for
# build(), the wheel and the licences; the archive's commit check and
# fresh unpacking (_ortf_unpack_mirror) on git archive fixtures; and the
# build information patch (_ortf_patch_git_info), whose string CMake
# makes exactly as 1.29.0-7's library has it, failing loudly on a
# patched or changed file. The PKGBUILD is copied with its CUDA root
# pointed at a fixture (the package names read its cuda.h when the file
# is sourced) and sourced in a subshell per case, with its other vendor
# locations pointed at fixtures under mktemp and pacman, python, cmake,
# readelf, patchelf and ldd replaced by stubs (pacman's vercmp,
# read-only, is the real one): no CUDA, TensorRT, OpenVINO or ROCm is
# needed, nothing is downloaded or built. Usage:
# scripts/tests/pkgbuild-settings-test.sh. Exits non-zero on any
# failure.
set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
recipe_pkgbuild=$(cd "$here/../../onnxruntime-split" && pwd)/PKGBUILD
# The cuda12 line's recipe, generated from it (scripts/gen-cuda12.sh).
recipe12_pkgbuild=$(cd "$here/../../onnxruntime-split-cuda12" && pwd)/PKGBUILD
# The migraphx line's (scripts/gen-migraphx.sh).
recipemgx_pkgbuild=$(cd "$here/../../onnxruntime-split-migraphx" && pwd)/PKGBUILD

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

fails=0 count=0
ok() { count=$((count + 1)); echo "ok   $1"; }
fail() { count=$((count + 1)); echo "FAIL $1"; fails=$((fails + 1)); }

# The vendor fixtures: a CUDA 13.4 (cuda.h, an nvcc that prints its
# release), a CUDA 12.8 (cuda.h, the same nvcc, run with FX_NVCC_RELEASE
# 12.x), a CUDA with nvcc but no cuda.h, a cuDNN 9.27, a cuDNN 9.10 and one
# without CUDNN_MINOR, an
# OpenVINO CMake package, and TensorRT trees (lib/ and lib64/, and ones
# without or with a bad NvInferVersion.h). Empty files otherwise: only
# their names count.
fx=$tmp/fx
mkdir -p "$fx/cuda/bin" "$fx/cuda/include" "$fx/cuda12/bin" "$fx/cuda12/include" "$fx/cuda-nohdr/bin" \
    "$fx/cuda-nodefine/include" "$fx/cudnn/include" "$fx/cudnn910/include" "$fx/cudnn-nominor/include" "$fx/cudnn-nohdr/include" "$fx/cudnn-nodefine/include" "$fx/cmake/openvino2026.4.1" \
    "$fx/trt/include" "$fx/trt/lib" "$fx/trt64/include" "$fx/trt64/lib64" "$fx/trt-nolib/include" \
    "$fx/trt-old/include" "$fx/trt-old/lib" "$fx/trt-nover/include" "$fx/trt-nover/lib" \
    "$fx/trt-badver/include" "$fx/trt-badver/lib" "$fx/trt-relver/include" "$fx/trt-relver/lib" \
    "$fx/empty" "$fx/bin" "$fx/pacbin" "$fx/pkgbin" "$fx/nccl/include"
# NCCL's header as Arch's nccl installs it (/usr/include/nccl.h): only its
# name counts.
: >"$fx/nccl/include/nccl.h"
# cuda.h as CUDA's: the version define some way down, after comments and
# other defines (line 272 in CUDA 13.4).
cuda_h() { # cuda_h <CUDA_VERSION>
    local i
    printf '/* A stand-in for cuda.h: the version define some way down. */\n#ifndef __cuda_cuda_h__\n'
    for ((i = 0; i < 250; i++)); do printf '#define CU_FILLER_%d %d\n' "$i" "$i"; done
    printf '/**\n * CUDA API version number\n */\n#define CUDA_VERSION %s\n\n#define CUDA_VERSION_LATER 99000\n' "$1"
}
cuda_h 13040 >"$fx/cuda/include/cuda.h"
cuda_h 12080 >"$fx/cuda12/include/cuda.h"
cuda_h 13040 | grep -v '^#define CUDA_VERSION ' >"$fx/cuda-nodefine/include/cuda.h"
# nvcc --version as CUDA's, with the release FX_NVCC_RELEASE (13.4), or
# none for FX_NVCC_RELEASE=none.
cat >"$fx/cuda/bin/nvcc" <<'EOF2'
#!/bin/sh
[ "$1" = --version ] || { echo "stub nvcc: unexpected $*" >&2; exit 2; }
echo 'nvcc: NVIDIA (R) Cuda compiler driver'
[ "${FX_NVCC_RELEASE:-}" = none ] && exit 0
r=${FX_NVCC_RELEASE:-13.4}
echo "Cuda compilation tools, release $r, V$r.92"
EOF2
chmod +x "$fx/cuda/bin/nvcc"
cp "$fx/cuda/bin/nvcc" "$fx/cuda-nohdr/bin/nvcc"
cp "$fx/cuda/bin/nvcc" "$fx/cuda12/bin/nvcc"
: >"$fx/cudnn/include/cudnn.h"
: >"$fx/cudnn910/include/cudnn.h"
: >"$fx/cudnn-nominor/include/cudnn.h"
: >"$fx/cudnn-nohdr/include/cudnn.h"
: >"$fx/cudnn-nodefine/include/cudnn.h"
# cudnn_version.h as cuDNN's, in its own words (no vendor text): the version
# defines among others.
cudnn_version_h() { # cudnn_version_h <CUDNN_MAJOR> [<CUDNN_MINOR>, default 27]
    printf '/* A stand-in for cudnn_version.h. */\n#ifndef CUDNN_VERSION_H_\n#define CUDNN_VERSION_H_\n'
    printf '#define CUDNN_MAJOR %s\n#define CUDNN_MINOR %s\n#define CUDNN_PATCHLEVEL 0\n' "$1" "${2:-27}"
    printf '#define CUDNN_MAX_SM_MAJOR_NUMBER 12\n#endif\n'
}
cudnn_version_h 9 >"$fx/cudnn/include/cudnn_version.h"
cudnn_version_h 9 | grep -v '^#define CUDNN_MAJOR ' >"$fx/cudnn-nodefine/include/cudnn_version.h"
cudnn_version_h 9 10 >"$fx/cudnn910/include/cudnn_version.h"
cudnn_version_h 9 | grep -v '^#define CUDNN_MINOR ' >"$fx/cudnn-nominor/include/cudnn_version.h"
: >"$fx/cmake/openvino2026.4.1/OpenVINOConfig.cmake"
# The CMake packages of Arch's spirv-headers, spirv-tools, vulkan-headers
# and vulkan-utility-libraries under a prefix, as the WebGPU provider's
# Dawn builds against them; webgpu-nospirv lacks SPIRV-Tools'.
for d in webgpu webgpu-nospirv; do
    for f in share/cmake/SPIRV-Headers/SPIRV-HeadersConfig.cmake lib/cmake/SPIRV-Tools/SPIRV-ToolsConfig.cmake \
        share/cmake/VulkanHeaders/VulkanHeadersConfig.cmake \
        lib/cmake/VulkanUtilityLibraries/VulkanUtilityLibrariesConfig.cmake; do
        mkdir -p "$fx/$d/${f%/*}"
        : >"$fx/$d/$f"
    done
done
rm "$fx/webgpu-nospirv/lib/cmake/SPIRV-Tools/SPIRV-ToolsConfig.cmake"
# The system python Dawn's generators run with: pyjinja's imports jinja2
# and markupsafe (it succeeds for exactly that -I -c), pynojinja's cannot.
mkdir -p "$fx/pyjinja" "$fx/pynojinja"
cat >"$fx/pyjinja/python" <<'EOF2'
#!/bin/sh
[ "$1" = -I ] && [ "$2" = -c ] && [ "$3" = 'import jinja2, markupsafe' ] && exit 0
exit 1
EOF2
printf '#!/bin/sh\necho "ModuleNotFoundError: No module named jinja2" >&2\nexit 1\n' >"$fx/pynojinja/python"
chmod +x "$fx/pyjinja/python" "$fx/pynojinja/python"
: >"$fx/trt/include/NvInfer.h"
: >"$fx/trt/lib/libnvinfer.so.11"
: >"$fx/trt64/include/NvInfer.h"
: >"$fx/trt64/lib64/libnvinfer.so"
: >"$fx/trt-nolib/include/NvInfer.h"
# NvInferVersion.h in both styles: TensorRT 10 and 11 (NV_TENSORRT_MAJOR is
# TRT_MAJOR_ENTERPRISE, ...), older ones (numbers).
cat >"$fx/trt/include/NvInferVersion.h" <<'EOF2'
#define TRT_MAJOR_ENTERPRISE 11
#define TRT_MINOR_ENTERPRISE 4
#define TRT_PATCH_ENTERPRISE 0
#define TRT_BUILD_ENTERPRISE 106
#define NV_TENSORRT_MAJOR TRT_MAJOR_ENTERPRISE //!< TensorRT major version.
#define NV_TENSORRT_MINOR TRT_MINOR_ENTERPRISE //!< TensorRT minor version.
#define NV_TENSORRT_PATCH TRT_PATCH_ENTERPRISE //!< TensorRT patch version.
#define NV_TENSORRT_BUILD TRT_BUILD_ENTERPRISE //!< TensorRT build number.
#define NV_TENSORRT_LWS_MAJOR 0 //!< TensorRT LWS major version.
EOF2
cp "$fx/trt/include/NvInferVersion.h" "$fx/trt64/include/NvInferVersion.h"
printf '#define NV_TENSORRT_MAJOR 8\n#define NV_TENSORRT_MINOR 6\n#define NV_TENSORRT_PATCH 1\n#define NV_TENSORRT_BUILD 6\n' \
    >"$fx/trt-old/include/NvInferVersion.h"
printf '#define NV_TENSORRT_MAJOR TRT_MAJOR_ENTERPRISE\n#define NV_TENSORRT_MINOR TRT_MINOR_ENTERPRISE\n' \
    >"$fx/trt-badver/include/NvInferVersion.h"
printf '#define NV_TENSORRT_MAJOR 10\n#define NV_TENSORRT_MINOR 13\n' >"$fx/trt-relver/include/NvInferVersion.h"
for d in trt-old trt-nover trt-badver trt-relver; do
    : >"$fx/$d/include/NvInfer.h"
    : >"$fx/$d/lib/libnvinfer.so"
done
printf "export NVCC_CCBIN='/usr/bin/g++-15'\n" >"$fx/cuda.sh"
# ROCm roots as Arch's migraphx and hip-runtime-amd lay them out under
# /opt/rocm: the CMake packages and the libraries with their runtime links
# (libmigraphx_c.so.3, libamdhip64.so.7, the sonames of ROCm 7.2 and 10.1).
# rocm-nocmake has the libraries only, rocm-nohip no HIP CMake package,
# rocm-twohip two HIP majors, rocm-nolib the CMake packages only.
rocm_tree() { # rocm_tree <dir> [cmake] [libs] [hip cmake]
    mkdir -p "$1/lib/cmake/migraphx" "$1/lib/cmake/hip"
    [[ ${2:-1} == 0 ]] || : >"$1/lib/cmake/migraphx/migraphx-config.cmake"
    [[ ${2:-1} == 0 || ${4:-1} == 0 ]] || : >"$1/lib/cmake/hip/hip-config.cmake"
    if [[ ${3:-1} == 1 ]]; then
        : >"$1/lib/libmigraphx_c.so.3.2007000"
        ln -s libmigraphx_c.so.3.2007000 "$1/lib/libmigraphx_c.so.3"
        ln -s libmigraphx_c.so.3 "$1/lib/libmigraphx_c.so"
        : >"$1/lib/libamdhip64.so.7.2.70204"
        ln -s libamdhip64.so.7.2.70204 "$1/lib/libamdhip64.so.7"
        ln -s libamdhip64.so.7 "$1/lib/libamdhip64.so"
    fi
    # RCCL's header, as Arch's rccl lays it out (include/rccl/rccl.h).
    mkdir -p "$1/include/rccl"
    : >"$1/include/rccl/rccl.h"
}
rocm_tree "$fx/rocm"
rocm_tree "$fx/rocm-nocmake" 0
rocm_tree "$fx/rocm-nohip" 1 1 0
rocm_tree "$fx/rocm-nolib" 1 0
rocm_tree "$fx/rocm-twohip"
: >"$fx/rocm-twohip/lib/libamdhip64.so.6"
rocm_tree "$fx/rocm-stale"
: >"$fx/rocm-stale/lib/libamdhip64.so.6.4.60400"
# A ROCm root without RCCL.
rocm_tree "$fx/rocm-norccl"
rm "$fx/rocm-norccl/include/rccl/rccl.h"
# Stubs found first on PATH by some cases. The python prints its version,
# FX_PYTHON_VERSION (default 3.14.8), for -I -c.
cat >"$fx/bin/python" <<'EOF2'
#!/bin/sh
[ "$1" = -I ] && [ "$2" = -c ] && printf '%s\n' "${FX_PYTHON_VERSION-3.14.8}"
exit 0
EOF2
printf '#!/bin/sh\nexit 0\n' >"$fx/bin/ccache"
chmod +x "$fx/bin/python" "$fx/bin/ccache"
# pacman, read-only queries only:
#   -T -- <dep>...: prints each dependency named in FX_MISSING (as not
#     satisfied) and exits 127 if there is one, else prints nothing;
#   -Qi -- <name>: the Name, Version and Provides lines of the installed
#     package of FX_INSTALLED that is or provides <name> (entries
#     name|version|provides, space-separated; provides comma-separated),
#     or fails as for a package not installed. The default: Arch's
#     openvino and cudnn, a local TensorRT package that provides tensorrt,
#     and Arch's migraphx, hip-runtime-amd and rccl of ROCm 7.2, and
#     Arch's spirv-headers and vulkan-headers (the WebGPU provider's).
cat >"$fx/pacbin/pacman" <<'EOF2'
#!/bin/sh
case $1 in
-Qi)
    [ "$2" = -- ] && shift
    for e in ${FX_INSTALLED-openvino|2026.4.1-1| cudnn|9.27.0.2-1| nvidia-tensorrt-sdk-local|11.4.0.106-2|tensorrt=11.4.0.106 migraphx|7.2.3-7| hip-runtime-amd|7.2.4-1|hip=7.2.4 rccl|7.2.4-1| spirv-headers|1:1.4.363.0-1| vulkan-headers|1:1.4.363.0-1|}; do
        n=${e%%|*} r=${e#*|} v=${r%%|*} p=${r#*|}
        hit=0
        [ "$n" = "$2" ] && hit=1
        for q in $(printf '%s' "$p" | tr ',' ' '); do
            [ "$q" = "$2" ] || [ "${q%%=*}" = "$2" ] && hit=1
        done
        if [ "$hit" = 1 ]; then
            printf 'Name            : %s\nVersion         : %s\n' "$n" "$v"
            printf 'Description     : a stub\nProvides        : %s\nDepends On      : None\n' "$(printf '%s' "${p:-None}" | sed 's/,/  /g')"
            exit 0
        fi
    done
    echo "error: package '$2' was not found" >&2
    exit 1
    ;;
-T)
    shift
    [ "$1" = -- ] && shift
    rc=0
    for d in "$@"; do
        case " ${FX_MISSING:-} " in *" $d "*) printf '%s\n' "$d"; rc=127 ;; esac
    done
    exit "$rc"
    ;;
esac
echo "stub pacman: unexpected $*" >&2
exit 2
EOF2
chmod +x "$fx/pacbin/pacman"

# The PKGBUILD as tested: the recipe's, its CUDA root FX_CUDA_HOME (default
# the CUDA 13.4 fixture), in a directory of its own for makepkg.
mkdir -p "$tmp/recipe"
pkgbuild=$tmp/recipe/PKGBUILD
sed "s|^_ortf_cuda_home=/opt/cuda\$|_ortf_cuda_home=\${FX_CUDA_HOME:-$fx/cuda}|" "$recipe_pkgbuild" >"$pkgbuild"
if grep -qxF "_ortf_cuda_home=\${FX_CUDA_HOME:-$fx/cuda}" "$pkgbuild"; then
    ok "the tested PKGBUILD reads the CUDA fixture"
else
    fail "the PKGBUILD has no line _ortf_cuda_home=/opt/cuda to point at the fixture"
fi
# The cuda12 line's, the same way; its cases run with pkgbuild set to it
# (on12).
mkdir -p "$tmp/recipe12"
pkgbuild12=$tmp/recipe12/PKGBUILD
sed "s|^_ortf_cuda_home=/opt/cuda\$|_ortf_cuda_home=\${FX_CUDA_HOME:-$fx/cuda}|" "$recipe12_pkgbuild" >"$pkgbuild12"
if grep -qxF "_ortf_cuda_home=\${FX_CUDA_HOME:-$fx/cuda}" "$pkgbuild12" && grep -qxF '_ortf_line=cuda12' "$pkgbuild12"; then
    ok "the tested cuda12 PKGBUILD reads the CUDA fixture and is the cuda12 line"
else
    fail "onnxruntime-split-cuda12/PKGBUILD has no line _ortf_cuda_home=/opt/cuda or _ortf_line=cuda12"
fi
# on12 <command...>: runs a case helper (resolve, expect_ok, package_run,
# ...) on the cuda12 line's PKGBUILD; it sets the same globals.
on12() {
    local saved=$pkgbuild
    pkgbuild=$pkgbuild12
    "$@" || :
    pkgbuild=$saved
}
# The migraphx line's, the same way (onmgx).
mkdir -p "$tmp/recipemgx"
pkgbuildmgx=$tmp/recipemgx/PKGBUILD
sed "s|^_ortf_cuda_home=/opt/cuda\$|_ortf_cuda_home=\${FX_CUDA_HOME:-$fx/cuda}|" "$recipemgx_pkgbuild" >"$pkgbuildmgx"
if grep -qxF "_ortf_cuda_home=\${FX_CUDA_HOME:-$fx/cuda}" "$pkgbuildmgx" && grep -qxF '_ortf_line=migraphx' "$pkgbuildmgx"; then
    ok "the tested migraphx PKGBUILD reads the CUDA fixture and is the migraphx line"
else
    fail "onnxruntime-split-migraphx/PKGBUILD has no line _ortf_cuda_home=/opt/cuda or _ortf_line=migraphx"
fi
onmgx() {
    local saved=$pkgbuild
    pkgbuild=$pkgbuildmgx
    "$@" || :
    pkgbuild=$saved
}

# resolve <env assignments...>: runs _ortf_resolve with the fixtures and the
# given environment (every ORTF_* variable, MAKEFLAGS, NVCC_CCBIN, CFLAGS
# and CXXFLAGS unset otherwise; FX_CUDA_DIR=cuda12 with FX_NVCC_RELEASE=12.x
# for a CUDA 12 toolkit). An ORTF_EPS given without cuda (nor, in the
# migraphx line, migraphx) gets ORTF_NCCL=0 unless ORTF_NCCL is given too
# (NCCL needs it; the cases of the NCCL default itself give ORTF_NCCL=,
# which counts as unset). Sets out (its output, stdout and stderr), status and conf
# (the file it wrote, empty when none).
resolve() {
    local dir a eps_words
    local -a nccl_off=()
    for a; do
        case $a in
            ORTF_NCCL=*) nccl_off=() && break ;;
            ORTF_EPS=?*)
                eps_words=" ${a#ORTF_EPS=} "
                eps_words=${eps_words//,/ }
                # migraphx gives NCCL (RCCL) in the migraphx line only.
                [[ $eps_words == *' cuda '* || ($pkgbuild == "$pkgbuildmgx" && $eps_words == *' migraphx '*) ]] ||
                    nccl_off=(ORTF_NCCL=0)
                ;;
        esac
    done
    dir=$(mktemp -d "$tmp/case.XXXXXX")
    status=0
    # shellcheck disable=SC2016 # the script expands its own arguments
    out=$(env -u ORTF_EPS -u ORTF_CUDA_ARCHS -u ORTF_NVCC_THREADS -u ORTF_TENSORRT_HOME \
        -u ORTF_PYTHON -u ORTF_CCACHE -u ORTF_NCCL -u ORTF_SOURCE -u MAKEFLAGS -u NVCC_CCBIN -u CFLAGS -u CXXFLAGS \
        ORTF_PYTHON=0 ORTF_CCACHE=0 "${nccl_off[@]}" "$@" bash -c '
            set -euo pipefail
            # shellcheck disable=SC1090
            . "$1"
            # pacman -T and -Qi for tensorrt.
            PATH=$2/pacbin:$PATH
            _ortf_cuda_home=$2/${FX_CUDA_DIR:-cuda} _ortf_cudnn_home=$2/cudnn _ortf_openvino_cmake_dir=$2/cmake
            _ortf_tensorrt_default=$2/trt _ortf_cuda_profile=$2/no-cuda.sh _ortf_rocm_home=$2/${FX_ROCM_HOME:-rocm}
            _ortf_nccl_home=$2/${FX_NCCL_HOME:-nccl} _ortf_webgpu_prefix=$2/${FX_WEBGPU_PREFIX:-webgpu}
            _ortf_system_python=$2/${FX_SYSTEM_PY:-pyjinja}/python
            [[ -z ${FX_CUDA_NOHDR:-} ]] || _ortf_cuda_home=$2/cuda-nohdr
            [[ -z ${FX_CUDNN_HOME:-} ]] || _ortf_cudnn_home=$2/$FX_CUDNN_HOME
            [[ -z ${FX_PROFILE:-} ]] || _ortf_cuda_profile=$2/cuda.sh
            [[ -z ${FX_NO_TRT_DEFAULT:-} ]] || _ortf_tensorrt_default=$2/empty
            [[ -z ${FX_USR:-} ]] || _ortf_tensorrt_usr=$2/trt64
            [[ -z ${FX_NO_VENDOR:-} ]] ||
                _ortf_cuda_home=$2/empty _ortf_cudnn_home=$2/empty _ortf_openvino_cmake_dir=$2/empty \
                    _ortf_rocm_home=$2/empty _ortf_nccl_home=$2/empty
            _ortf_resolve "$3/ortf.conf"
        ' _ "$pkgbuild" "$fx" "$dir" 2>&1) || status=$?
    conf=''
    [[ ! -f $dir/ortf.conf ]] || conf=$(<"$dir/ortf.conf")
}

# expect_ok <description> <KEY=value...> -- <env...>: resolve succeeds and
# ortf.conf has each KEY=value line.
expect_ok() {
    local desc=$1 line missing=''
    shift
    local -a want=()
    while (($#)) && [[ $1 != -- ]]; do want+=("$1"); shift; done
    shift
    resolve "$@"
    if ((status != 0)); then
        fail "$desc (exit $status): $out"
        return
    fi
    for line in "${want[@]}"; do
        grep -qxF -- "$line" <<<"$conf" || missing+=" [$line]"
    done
    if [[ -n $missing ]]; then fail "$desc: ortf.conf lacks$missing: $conf"; else ok "$desc"; fi
}

# expect_fail <description> <message fragment> <env...>: resolve fails,
# writes no ortf.conf and says <message fragment>.
expect_fail() {
    local desc=$1 msg=$2
    shift 2
    resolve "$@"
    if ((status == 0)); then
        fail "$desc: succeeded: $out"
    elif [[ -n $conf ]]; then
        fail "$desc: wrote ortf.conf anyway"
    elif ! grep -qF -- "$msg" <<<"$out"; then
        fail "$desc: message lacks '$msg': $out"
    else
        ok "$desc"
    fi
}

