fi
expect_ok "the rtx preset expands to its list" 'ORTF_CUDA_ARCHS=75;86;89;120' 'ORTF_CUDA_PRESET=rtx' -- \
    ORTF_EPS=cuda ORTF_CUDA_ARCHS=rtx
