# The Maxwell trial: a copy of the cuda12 recipe with the list as its
# default (a clean chroot, where the environment does not reach makepkg).
mkdir -p "$tmp/recipe12-maxwell"
sed 's/^_ortf_default_cuda_archs=.*/_ortf_default_cuda_archs="50 52 60 61 70 75 80 86 89 120 50-virtual"/' \
    "$pkgbuild12" >"$tmp/recipe12-maxwell/PKGBUILD"
saved_pkgbuild=$pkgbuild
pkgbuild=$tmp/recipe12-maxwell/PKGBUILD
