    package_run "$conf" --
    if ((status == 0)) && [[ $(<"${pkgroot%/pkg}/rpath/libonnxruntime_providers_tensorrt.so") == "$want" ]] &&
        grep -qF "RUNPATH $want" "${pkgroot%/pkg}/$trt.log"; then
        ok "a TensorRT build against $name: RUNPATH $want"
