if ((status == 0)) && [[ $(<"$pkgroot/$wg/usr/share/licenses/$wg/dawn-LICENSE") == 'dawn licence stand-in' ]] &&
    [[ -z $(find "$pkgroot" -name dawn-LICENSE ! -path "$pkgroot/$wg/*") ]]; then
