@ONNXRUNTIME_IMPORT_PYTORCH_TO_RESOLVE_DLLS@
@ONNXRUNTIME_SETDLOPENFLAGS_GLOBAL@
from .onnxruntime_pybind11_state import *  # noqa
@ONNXRUNTIME_SETDLOPENFLAGS_LOCAL@
EOF2
