# shellcheck disable=SC2016 # a literal ${
if ((status == 0)) && ! diff "$pb_up" "$pb" | grep -q '^<' &&
    [[ $(grep -cxF 'from .onnxruntime_pybind11_state import *  # noqa' "$pb") == 1 ]] &&
