    grep -qxF '    get_available_providers = _ortf_wrap_available_providers(  # noqa: F405' "$pb" &&
    grep -qF 'omarchy-onnxruntime (onnxruntime-split/PKGBUILD, _ortf_patch_pybind_providers)' "$pb" &&
    ! grep -qF '${' "$pb" &&
