else
    fail "the Python module's WebGPU patch (exit $status): $out"$'\n'"$(diff "$pw_up" "$pw")"
fi
cp -- "$pw" "$pw.once"
patch_tops _ortf_patch_pybind_webgpu "$pw"
if ((status != 0)) && grep -qF 'look at the file and update _ortf_patch_pybind_webgpu' <<<"$out" && cmp -s "$pw" "$pw.once"; then
    ok "a second Python module WebGPU patch fails loudly and leaves the file as it was"
else
    fail "a second Python module WebGPU patch (exit $status): $out"
fi
wc_up=$tmp/conv2d_mm.cc.upstream
moe_git onnxruntime/core/providers/webgpu/nn/conv2d_mm.cc "$wc_up" || cat >"$wc_up" <<'EOF2'
  const std::string coord_a_snippet = is_channels_last_ ? "let coord = vec4<i32>(batch, xRow, xCol, xCh / " + std::to_string(inner_element_size_x == 3 ? 4 : inner_element_size_x) + ");" : "let coord = vec4<i32>(batch, xCh, xRow, xCol);";
EOF2
wc=$tmp/conv2d_mm.cc
cp -- "$wc_up" "$wc"
patch_tops _ortf_patch_webgpu_conv "$wc"
# One line replaced: the channel index divided by 1 for the 3-wide read.
