fi
cp -- "$wc" "$wc.once"
patch_tops _ortf_patch_webgpu_conv "$wc"
if ((status != 0)) && grep -qF 'look at the file and update _ortf_patch_webgpu_conv' <<<"$out" && cmp -s "$wc" "$wc.once"; then
