    grep -qxF '  _ortf_patch_pybind_webgpu onnxruntime/python/onnxruntime_pybind_state.cc || return 1' "$pkgbuild" &&
    grep -qxF '  _ortf_patch_webgpu_conv onnxruntime/core/providers/webgpu/nn/conv2d_mm.cc || return 1' "$pkgbuild"; then
